  accion,
  session_token: norm(b.session_token),
  evento_id: norm(b.evento_id).toUpperCase(),
  inscripcion_id: norm(b.inscripcion_id).toUpperCase(),
  nombre_acreditacion: norm(b.nombre_acreditacion).replace(/\s+/g, ' ').slice(0, 80),
  observaciones: norm(b.observaciones).slice(0, 300),
};
if (!d.session_token) return fallo(401, 'Inicia sesión para continuar.');
if (accion === 'crear' && !d.evento_id) return fallo(400, 'Falta el evento.');
if (['actualizar', 'cancelar'].includes(accion) && !d.inscripcion_id) return fallo(400, 'Falta la inscripción.');
