const base = { usuario_id: u.usuario_id, evento_id: d.evento_id };
const rechazar = (status, motivo) => fallo(status, motivo, { auditoria: auditar(base, 'CREAR', '', '', 'RECHAZADO', motivo) });

const telegram = filas('Leer Vinculación Telegram').find((v) => v.usuario_id === u.usuario_id && v.estado === 'ACTIVA');
if (!telegram) return rechazar(409, 'Vincula tu cuenta de Telegram desde tu perfil antes de inscribirte.');
