if (!evento) return rechazar(404, 'Ese evento no existe.');
if (evento.estado !== 'PUBLICADO') {
  const motivo = { CANCELADO: 'fue cancelado', CERRADO: 'cerró sus inscripciones', BORRADOR: 'aún no está publicado' }[evento.estado] || 'no está disponible';
  return rechazar(409, `Este evento ${motivo}.`);
}
if (inicioEvento(evento).getTime() <= Date.now()) return rechazar(409, 'Este evento ya empezó; las inscripciones están cerradas.');
