  auditoria_id: nuevoId('AUDI'), inscripcion_id: ins.inscripcion_id || '', usuario_id: ins.usuario_id || '', evento_id: ins.evento_id || '',
  accion, estado_anterior, estado_nuevo, fecha: ahora(), resultado, detalle,
});
const d = $('Validar solicitud').first().json;
const u = $('Validar sesión y usuario').first().json;
const ins = filas('Leer Inscripciones').find((i) => i.inscripcion_id === d.inscripcion_id);
// Una inscripción ajena se reporta igual que una inexistente.
if (!ins || ins.usuario_id !== u.usuario_id) return fallo(404, 'No encontramos esa inscripción en tu cuenta.');
const evento = filas('Leer Eventos').find((e) => e.evento_id === ins.evento_id) || {};
if (ins.estado === 'CANCELADA') return fallo(409, 'Esta inscripción ya estaba cancelada.');
if (inicioEvento(evento).getTime() <= Date.now()) return fallo(409, 'El evento ya empezó; la inscripción no se puede cancelar.');
const nuevo = { ...ins, estado: 'CANCELADA', orden_espera: '', fecha_actualizacion: ahora() };
const liberaCupo = ins.estado === 'CONFIRMADA';
return [{ json: {
  ok: true,
  ...nuevo,
  _auditoria: auditar(nuevo, 'CANCELAR', ins.estado, 'CANCELADA', 'OK', liberaCupo ? 'Cupo liberado; WF07 lo reasignará' : 'Salida de la lista de espera'),
  _respuesta: { ok: true, mensaje: 'Inscripción cancelada.', inscripcion: { inscripcion_id: nuevo.inscripcion_id, estado: 'CANCELADA' } },
  _notificacion: {
    usuario_id: ins.usuario_id, evento_id: ins.evento_id, inscripcion_id: ins.inscripcion_id,
    tipo: 'INSCRIPCION_CANCELADA', titulo: `Cancelaste tu inscripción: ${evento.nombre || ins.evento_id}`,
    mensaje: liberaCupo
      ? 'Tu cupo quedó libre y se asignará a la siguiente persona en lista de espera. Puedes volver a inscribirte si aún hay cupos.'
      : 'Saliste de la lista de espera de este evento.',
    clave_idempotencia: `INSCRIPCION_CANCELADA|${ins.inscripcion_id}`,
  },
} }];
